WITH filtered AS (SELECT id, account_id, txn_time, merchant, is_flagged, CONCAT_WS('-', merchant, txn_type) AS merchant_txn_type_key, COALESCE(merchant, 'N/A') AS merchant_clean FROM transactions WHERE merchant IS NOT NULL), metrics AS (SELECT *, ROW_NUMBER() OVER w_recent AS seq_no, ROW_NUMBER() OVER w_recent AS seq_no_2 FROM filtered WHERE txn_time < '2023-08-01' WINDOW w_recent AS (ORDER BY txn_time DESC, id)), cleaned AS (SELECT id, account_id, txn_time, merchant, is_flagged, merchant_clean, seq_no, seq_no_2, FLOOR(seq_no_2) AS seq_no_2_whole FROM metrics WHERE merchant IS NOT DISTINCT FROM 'Amazon' AND is_flagged), metrics_transactions AS (SELECT id, account_id, txn_time, is_flagged, merchant_clean, seq_no, seq_no_2, CUME_DIST() OVER w_grp AS seq_no_2_cume_dist, PERCENT_RANK() OVER (PARTITION BY account_id ORDER BY seq_no_2_whole NULLS FIRST) AS seq_no_2_whole_percent_rank, STDDEV_SAMP(seq_no_2_whole) OVER (PARTITION BY merchant) AS merchant_stddev_samp_seq_no_2_whole FROM cleaned WINDOW w_grp AS (PARTITION BY account_id ORDER BY seq_no_2 NULLS LAST)), base AS (SELECT *, YEAR(txn_time) AS txn_time_year, DATEDIFF(CURRENT_DATE(), txn_time) AS days_since_txn_time FROM metrics_transactions WHERE txn_time >= TO_TIMESTAMP('2023-09-02 03:00:00')), joined AS (SELECT e.id, e.account_id, e.txn_time, e.seq_no_2_whole_percent_rank, e.merchant_stddev_samp_seq_no_2_whole, e.days_since_txn_time, b.account_type, b.status FROM base e LEFT JOIN accounts b ON e.account_id = b.id), valid AS (SELECT *, CASE WHEN status = 'CLOSED' THEN 1 ELSE 0 END AS is_closed, COALESCE(status, 'N/A') AS status_filled, COALESCE(account_type, 'UNKNOWN') AS account_type_filled FROM joined WHERE account_id = 23 AND status IS DISTINCT FROM 'CLOSED') SELECT s.id, s.account_id, s.merchant_stddev_samp_seq_no_2_whole, s.days_since_txn_time, s.is_closed, s.account_type_filled, (SELECT SUM(x.amount) FROM transactions x WHERE x.account_id = s.account_id) AS sum_transaction_amount FROM valid s ORDER BY is_closed NULLS FIRST, id
